    let sid = generate_session_id();  let default_shell = Shell::from_name(program).unwrap_or(if cfg!(windows) { Shell::Pwsh } else { Shell::Bash });
    let (cpr, terminal_bg, typeahead) = probe_terminal(&*output, PROBE_TIMEOUT, platform::read_timeout);            // 433-443
    let late_probe_until = cpr.is_none().then(|| Instant::now() + LATE_PROBE);                                       // 445
    if cpr.is_none() { output.write(b"\x1b[H\x1b[2J"); }                                                             // 448 (before detect(), D10)
